  bracketTop: { en: `mellemskat (middle-income tax)`, nl: `mellemskat (middenbelasting)`, fr: `mellemskat (impôt moyen)` },
  trapTitle: {
    en: (a, b) => `Why is the rate lower between ${a} and ${b}?`,
    nl: (a, b) => `Waarom is het tarief lager tussen ${a} en ${b}?`,
    fr: (a, b) => `Pourquoi le taux est-il plus bas entre ${a} et ${b} ?`,
  },
  trapBody: {
    en: (a, b, job, max) => `Below ${a}, your pay is under the tax-free amount, so only the 8% labour market contribution (AM-bidrag) is taken. Above it, two deductions for working grow with your pay: the employment deduction (12.75%) and, from ${job}, the job deduction (4.5%). Part of each extra krone is not taxed, so it is taxed a bit less. At ${b} the employment deduction reaches its maximum of ${max}, and the rate on the next krone goes up. Your employer's fixed charges (ATP pension, AUB training fund, Barsel.dk parental leave fund) weigh more on low pay, so the full rate is higher at the very bottom.`,
    nl: (a, b, job, max) => `Onder ${a} ligt je loon onder het belastingvrije bedrag, dus gaat er alleen de arbeidsmarktbijdrage van 8% (AM-bidrag) af. Daarboven groeien twee aftrekken voor werkenden mee met je loon: de arbeidsaftrek (12,75%) en vanaf ${job} de jobaftrek (4,5%). Een deel van elke extra kroon wordt niet belast, dus wordt hij iets minder belast. Bij ${b} bereikt de arbeidsaftrek zijn maximum van ${max}, en stijgt het tarief op de volgende kroon. De vaste lasten van je werkgever (ATP-pensioen, opleidingsfonds AUB, fonds voor ouderschapsverlof Barsel.dk) wegen zwaarder op lage lonen, daarom is het totale tarief helemaal onderaan hoger.`,
    fr: (a, b, job, max) => `Sous ${a}, votre salaire est sous le montant sans impôt : seule la contribution de 8% au marché du travail (AM-bidrag) est prise. Au-delà, deux déductions pour ceux qui travaillent grandissent avec votre salaire : la déduction pour emploi (12,75%) et, à partir de ${job}, la déduction « job » (4,5%). Une partie de chaque couronne en plus n'est pas imposée, elle est donc un peu moins taxée. À ${b}, la déduction pour emploi atteint son maximum de ${max}, et le taux sur la couronne suivante monte. Les charges fixes de votre employeur (retraite ATP, fonds de formation AUB, fonds de congé parental Barsel.dk) pèsent plus sur les bas salaires, d'où un taux total plus élevé tout en bas.`,
  },
  topTitle: {
    en: (mel, top) => `Why the steps at ${mel}${top ? ` and ${top}` : ''}?`,
    nl: (mel, top) => `Waarom de sprongen bij ${mel}${top ? ` en ${top}` : ''}?`,
    fr: (mel, top) => `Pourquoi les marches à ${mel}${top ? ` et ${top}` : ''} ?`,
  },
  topBody: {
    en: (mel, top, tt, amt) => `From ${mel}, your income after the labour market contribution goes above ${amt}, and the 7.5% middle-income tax (mellemskat) starts.${top ? ` From ${top}, the new 7.5% top tax (topskat) is added.` : ''}${tt ? ` From ${tt}, the 5% extra top tax (toptopskat) comes on top.` : ''} There is a ceiling: municipal tax + basic state tax (bundskat) + middle-income tax can't go above 44.57% together. The top taxes come on top of that ceiling.`,
    nl: (mel, top, tt, amt) => `Vanaf ${mel} komt je inkomen na de arbeidsmarktbijdrage boven ${amt}, en begint de middenbelasting van 7,5% (mellemskat).${top ? ` Vanaf ${top} komt de nieuwe topbelasting van 7,5% (topskat) erbij.` : ''}${tt ? ` Vanaf ${tt} komt daar nog de extra topbelasting van 5% (toptopskat) bij.` : ''} Er is een plafond: gemeentebelasting + basisbelasting van de staat (bundskat) + middenbelasting samen mogen niet boven 44,57%. De topbelastingen komen bovenop dat plafond.`,
    fr: (mel, top, tt, amt) => `À partir de ${mel}, votre revenu après la contribution au marché du travail dépasse ${amt}, et l'impôt moyen de 7,5% (mellemskat) commence.${top ? ` À partir de ${top}, le nouvel impôt supérieur de 7,5% (topskat) s'ajoute.` : ''}${tt ? ` À partir de ${tt}, l'impôt supérieur en plus de 5% (toptopskat) vient par-dessus.` : ''} Il y a un plafond : impôt communal + impôt d'État de base (bundskat) + impôt moyen ne peuvent pas dépasser ensemble 44,57%. Les impôts supérieurs s'ajoutent au-dessus de ce plafond.`,
  },

